    protected function tearDown():void
    {
        global $wpdb;$wpdb->query('ROLLBACK');foreach($this->selections as $selection){$wpdb->delete(Tables::research_candidate_evidence(),['candidate_id'=>$selection['candidate']]);$wpdb->delete(Tables::research_reviews(),['candidate_id'=>$selection['candidate']]);$wpdb->delete(Tables::research_candidates(),['id'=>$selection['candidate']]);$wpdb->delete(Tables::research_evidence(),['id'=>$selection['evidence']]);$wpdb->delete(Tables::research_observations(),['id'=>$selection['observation']]);$wpdb->delete(Tables::research_sources(),['id'=>$selection['source']]);self::assertNull($wpdb->get_var($wpdb->prepare('SELECT id FROM '.Tables::research_candidates().' WHERE id=%d',$selection['candidate'])));}remove_filter('pre_http_request',$this->http);if($this->scope!==null)remove_filter('query',$this->scope,1);Settings::protectProduction();self::assertTrue(Settings::safety_locked());self::assertFalse(Settings::get('automation_armed',false));self::assertTrue(Settings::get('stop_all',true));$wpdb->query('START TRANSACTION');parent::tearDown();
