    private function render(string $shop='digital',array $extra=[]):string
    {
        $prior=$_GET;try{$_GET=['df_view'=>'research','df_shop'=>$shop]+$extra;return (new Portal())->render();}finally{$_GET=$prior;}
    }
    private function invoke(string $action,array $body,bool $error):array
    {
        (new Portal())->register();$prior=$_POST;$request=$_REQUEST;$url='';$capture=static function(string $target)use(&$url):never{$url=$target;throw new RuntimeException('local-research-return');};add_filter('wp_redirect',$capture);try{$_POST=$_REQUEST=$body+['_wpnonce'=>wp_create_nonce($action)];try{do_action('admin_post_'.$action);self::fail('Portal action must return.');}catch(RuntimeException $e){self::assertSame('local-research-return',$e->getMessage());}}finally{remove_filter('wp_redirect',$capture);$_POST=$prior;$_REQUEST=$request;}parse_str((string)parse_url($url,PHP_URL_QUERY),$query);self::assertSame($error?'1':'0',(string)($query['df_error']??''),$query['df_message']??'Portal return');return $query;
    }
