    }
    private function releasedPolicy(string $shop='digital'):void
    {
        // Existing DeepResearchAcceptanceTest isolation and explicit local activation contract.
        global $wpdb;$isolated=[];$next=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0)+1000 FROM '.Tables::shop_ai_usage());foreach([Tables::shop_ai_usage(),Tables::shop_ai_policies()]as $table){$isolated[$table]=$table.'_'.substr(str_replace('-','',wp_generate_uuid4()),0,12);self::assertNotFalse($wpdb->query('CREATE TEMPORARY TABLE '.$isolated[$table].' LIKE '.$table));}self::assertNotFalse($wpdb->query('ALTER TABLE '.$isolated[Tables::shop_ai_usage()].' AUTO_INCREMENT = '.$next));$this->scope=static fn(string $sql):string=>str_replace(array_keys($isolated),array_values($isolated),$sql);add_filter('query',$this->scope,1);Settings::set('research',true);Settings::set('ai',true);self::assertTrue(Settings::activateResearch());self::assertTrue(Settings::activateAi());self::assertNotFalse($wpdb->query('START TRANSACTION'));self::assertNotWPError((new DigiForge\AI\ShopAiGovernanceRepository())->savePolicy(['shop_key'=>$shop,'currency'=>'USD','stages'=>['research'=>['limit'=>2,'monthly_budget'=>'1'],'shortlist'=>['limit'=>2,'monthly_budget'=>'1']]]));
    }
    private function form(string $html,string $action):array
    {
        $doc=new DOMDocument();$prior=libxml_use_internal_errors(true);try{$doc->loadHTML($html,LIBXML_NONET);}finally{libxml_clear_errors();libxml_use_internal_errors($prior);}$xpath=new DOMXPath($doc);$forms=$xpath->query('//form[input[@name="action" and @value="'.$action.'"]]');self::assertSame(1,$forms->length);$pairs=[];foreach($xpath->query('.//input[@type="hidden"]',$forms->item(0))as $node)$pairs[]=urlencode($node->getAttribute('name')).'='.urlencode($node->getAttribute('value'));parse_str(implode('&',$pairs),$body);self::assertTrue(wp_verify_nonce($body['_wpnonce'],$action)!==false);return $body;
    }
    public function testProtectedPortalShowsManualRunBoundaryAndCannotReadCredentialsOrCallProvider():void
    {
        $html=$this->render();self::assertStringContainsString('Manual research run',$html);self::assertStringContainsString('STOP ALL',$html);$reads=[];$capture=static function(string $sql)use(&$reads):string{if(str_starts_with($sql,'SELECT')&&str_contains($sql,Tables::integration_secrets()))$reads[]=$sql;return $sql;};add_filter('query',$capture);try{$this->invoke(ResearchRunWorkflow::PREPARE_ACTION,['shop_key'=>'digital','phase'=>'trend_scan','query'=>'Synthetic protected question'],true);}finally{remove_filter('query',$capture);}self::assertSame([],$reads);self::assertSame(0,$this->httpCalls);
    }
    /** @dataProvider shopCases */
