        $payload=['title'=>'Synthetic Portal analysis','summary'=>'Offline selected-candidate research only.','signals'=>['demand'=>80,'competition_gap'=>60,'margin'=>50,'trend'=>40,'evidence_quality'=>70],'analysis'=>['demand_evidence'=>'Synthetic demand','competition_saturation'=>'Synthetic competition','provider_feasibility'=>'Uncertified supplier route','confidence_uncertainty'=>'Synthetic fixture only'],'observations'=>[]];$this->response=['id'=>'resp_'.str_replace('-','',wp_generate_uuid4()),'status'=>'completed','model'=>$contract['model'],'output_text'=>wp_json_encode($payload),'usage'=>['input_tokens'=>20,'output_tokens'=>10,'total_tokens'=>30]];
        $prepare=$this->form($this->render($shop),ResearchRunWorkflow::PREPARE_ACTION);$return=$this->invoke(ResearchRunWorkflow::PREPARE_ACTION,array_replace($prepare,['phase'=>'deep_research','selected_candidate_id'=>(string)$id]),false);$consent=$this->form($this->render($shop,['df_research_run'=>$return['df_research_run']]),ResearchRunWorkflow::EXECUTE_ACTION);$consent['df_confirm_research_run']='1';$routes=[];$observe=static function($result,array $handler,WP_REST_Request $request)use(&$routes){$routes[]=$request->get_route();return $result;};add_filter('rest_request_before_callbacks',$observe,11,3);try{$completed=$this->invoke(ResearchRunWorkflow::EXECUTE_ACTION,$consent,false);}finally{remove_filter('rest_request_before_callbacks',$observe,11);}self::assertContains('/digiforge/v1/launch/research',$routes);self::assertSame(1,$this->httpCalls);$candidate=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::research_candidates().' WHERE id=%d',(int)$completed['df_candidate']),ARRAY_A);self::assertSame('PENDING',$candidate['review_status']);self::assertNotSame($id,(int)$candidate['id']);self::assertSame($before,$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::research_candidates().' WHERE id=%d',$id),ARRAY_A));self::assertSame('1',$wpdb->get_var($wpdb->prepare('SELECT SUM(quantity) FROM '.Tables::shop_ai_usage().' WHERE shop_key=%s AND stage=%s',$shop,'shortlist')));$this->invoke(ResearchRunWorkflow::EXECUTE_ACTION,$consent,true);self::assertSame(1,$this->httpCalls);
    }
