        $input=['shop'=>'jewelry','phase'=>'trend_scan','market'=>'Offline fixture market','focus'=>'Rights-safe fictional jewelry concepts','query'=>'Synthetic demand questions only'];$contract=$engine->researchPreview($input);self::assertNotWPError($contract);$quote=['provider'=>'openai','quote_id'=>'synthetic-trend-'.wp_generate_uuid4(),'model'=>$contract['model'],'request_sha256'=>$contract['request_sha256'],'currency'=>'USD','maximum_charge'=>'0.1','inclusive_all_charges'=>true,'valid_from'=>gmdate('Y-m-d\TH:i:s\Z',time()-60),'valid_until'=>gmdate('Y-m-d\TH:i:s\Z',time()+600)];self::assertNotWPError((new DigiForge\AI\MonetaryReservationRepository())->reviewQuote('jewelry',(string)wp_json_encode($quote),'CONFIRM_PROVIDER_QUOTE'));
        $this->response=['id'=>'resp_'.str_replace('-','',wp_generate_uuid4()),'status'=>'completed','model'=>$contract['model'],'output_text'=>wp_json_encode(['title'=>'Synthetic trend '.wp_generate_uuid4(),'summary'=>'No commercial evidence','signals'=>[],'observations'=>[]]),'usage'=>['input_tokens'=>20,'output_tokens'=>10,'total_tokens'=>30]];
